input.command:
U=/private/tmp/claude-501/-Users-itome-shopbench-runs-exact/6b4090c8-2e55-4392-84a6-92e2e5a573cd/scratchpad/uitest; cat > $U/UITests/EverbloomUITests.swift <<EOF
import XCTest

let SYNC = "$U"

final class EverbloomUITests: XCTestCase {
    var app: XCUIApplication!
    override func setUp() { continueAfterFailure = false }

    func el(_ id: String) -> XCUIElement { app.descendants(matching: .any).matching(identifier: id).firstMatch }
    func need(_ id: String, _ t: TimeInterval = 15, file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertTrue(el(id).waitForExistence(timeout: t), "missing \(id)", file: file, line: line)
        print("FOUND \(id)")
    }
    func tap(_ id: String) { need(id); el(id).tap() }
    func launch(_ env: [String: String] = [:]) {
        app = XCUIApplication(bundleIdentifier: "dev.whiskerrs.shopbench.exact")
        app.launchEnvironment = env
        app.terminate()
        app.launch()
    }
    func scrollUp(_ id: String, _ n: Int) { for _ in 0..<n { el(id).swipeUp(velocity: .fast) } }

    func testWalkthrough() {
        launch()
        for id in ["tab-home", "tab-search", "tab-cart", "home-scroll", "collection-chip-0", "featured-collection", "collection-card-0", "best-seller-0"] { need(id) }
        // Collection: sorts, scroll to the end.
        tap("collection-chip-0")
        for id in ["product-grid", "sort-featured", "sort-best-selling", "sort-price-asc", "sort-price-desc", "product-card-0", "back"] { need(id) }
        for s in ["sort-best-selling", "sort-price-asc", "sort-price-desc", "sort-featured"] { tap(s); need("product-card-0") }
        scrollUp("product-grid", 25)
        tap("back")
        // Product: options, carousel, recommendation, add to cart.
        tap("best-seller-0")
        for id in ["product-carousel", "add-to-cart", "back"] { need(id) }
        el("product-carousel").swipeLeft()
        let pills = app.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'option-'"))
        print("PILLS \(pills.count) \(pills.allElementsBoundByIndex.map { \$0.identifier })")
        if pills.count > 1 { pills.element(boundBy: 1).tap() }
        app.swipeUp()
        tap("recommendation-0")
        need("add-to-cart")
        tap("back")
        tap("add-to-cart")
        need("cart-line-0"); need("cart-badge")
        print("BADGE \(el("cart-badge").label) SUBTOTAL \(el("cart-subtotal").label)")
        for id in ["qty-dec-0", "qty-inc-0", "cart-subtotal", "checkout"] { need(id) }
        tap("qty-inc-0")
        sleep(3)
        print("SUBTOTAL2 \(el("cart-subtotal").label)")
        // Check out: the in-app browser over the app.
        tap("checkout")
        let done = app.buttons["Done"].firstMatch
        let safari = done.waitForExistence(timeout: 15)
        print("SAFARI \(safari)")
        XCUIScreen.main.screenshot().pngRepresentation.write(to: URL(fileURLWithPath: SYNC + "/checkout.png"))
        if safari { done.tap() }
        tap("qty-dec-0"); sleep(3); tap("qty-dec-0")
        XCTAssertTrue(el("cart-line-0").waitForNonExistence(timeout: 15))
        XCTAssertFalse(el("cart-badge").exists)
        // Search.
        tap("tab-search")
        tap("search-input")
        el("search-input").typeText("shirt")
        need("search-results"); need("search-result-0")
        scrollUp("search-results", 15)
        tap("tab-search")
        print("DONE walkthrough")
    }

    func testErrorThenRetry() throws {
        launch(["SHOP_API_URL": "http://127.0.0.1:8787/api"])
        need("error-retry", 40)
        try Data().write(to: URL(fileURLWithPath: SYNC + "/error-seen"))
        let up = Date().addingTimeInterval(60)
        while !FileManager.default.fileExists(atPath: SYNC + "/proxy-up") && Date() < up { sleep(1) }
        sleep(2)
        tap("error-retry")
        need("best-seller-0", 30)
        need("collection-chip-0")
        print("DONE retry")
    }
}
EOF
cd $U && xcodebuild -project UI.xcodeproj -scheme UITests -destination 'platform=iOS Simulator,id=C21C6F65-13BD-45A0-A12A-E1361CBA4109' -derivedDataPath $U/dd build-for-testing 2>&1 | tail -3

